import argparse
import json
from pathlib import Path

from inventory.export import export_csv
from inventory.report import format_report
from inventory.settings import DEFAULTS, load_settings


def build_parser():
    parser = argparse.ArgumentParser(prog="inventory")
    commands = parser.add_subparsers(dest="command", required=True)
    report = commands.add_parser("report", help="print stock levels and total value")
    report.add_argument("--warehouse")
    report.add_argument("--data", default="data/items.json")
    export = commands.add_parser("export", help="write items as CSV")
    export.add_argument("--currency")
    export.add_argument("--data", default="data/items.json")
    return parser


def resolve_options(args, settings):
    options = {**DEFAULTS, **{key: value for key, value in vars(args).items() if value is not None}}
    options.update(settings)
    return options


def main(argv=None):
    args = build_parser().parse_args(argv)
    options = resolve_options(args, load_settings())
    items = json.loads(Path(options["data"]).read_text())
    if options["command"] == "report":
        print(format_report(items, options["warehouse"]))
    else:
        print(export_csv(items, options["currency"]), end="")
    return 0

