CODES = {"SAVE10": 10, "SAVE25": 25}


def percent_off(order, percent):
    return (order.subtotal_cents() + order.shipping_cents) * percent // 100


def apply_code(order, code):
    percent = CODES.get(code.upper())
    if percent is None:
        raise ValueError(f"unknown code {code}")
    order.discount_cents = percent_off(order, percent)
    return order

